select public.seed_wines('[{"s":"yangarra-estate-old-vine-grenache","n":"Old Vine Grenache","p":"Yangarra Estate Vineyard","t":"red","c":"Australia","r":"South Australia","a":"McLaren Vale","g":["Grenache"],"pr":38,"abv":14.5,"e":"Wild-fermented with some whole bunches; about 10 months in seasoned large-format French oak","sv":"14–16°C","d":"30 minutes","w":"Now–12 years","ds":"Bush vines planted in the 1940s on the deep sands of Blewitt Springs give Grenache of real perfume: raspberry, red cherry and rose petal laced with garrigue and white pepper. The tannins are fine and sandy, the fruit juicy rather than heavy, a long way from the jammy Grenache of old.","x":"284:3,285:55,286:50,287:72,288:62,289:75,290:72,291:15,292:0,293:18,3:85,1:70,9:45,4:35,8:30,72:35,71:20,106:50,111:30,121:35,134:30,127:15,152:25,153:30,214:60,212:45,229:60,231:50,252:75,236:65,240:60,262:35,260:50,278:80,265:30,279:60,282:45,295:100,299:100,301:100,314:100"},{"s":"wynns-coonawarra-estate-black-label-cabernet-sauvignon","n":"Black Label Cabernet Sauvignon","p":"Wynns Coonawarra Estate","t":"red","c":"Australia","r":"South Australia","a":"Coonawarra","g":["Cabernet Sauvignon"],"pr":40,"abv":13.5,"e":"About 15 months in French oak barriques, roughly a quarter new","sv":"16–18°C","d":"1 hour when young","w":"5–25 years from vintage","ds":"Australia''s benchmark Cabernet from the terra rossa strip: cassis and mulberry framed by the region''s unmistakable mint and eucalyptus, with cedar and a fine, gravelly grip. Medium-weight and cool-toned, it ages for decades into something close to claret.","x":"284:2,285:62,286:72,287:55,288:70,289:72,290:75,291:45,292:0,293:20,13:90,17:55,14:45,12:35,97:75,98:70,99:30,93:35,105:20,159:50,156:25,157:20,168:20,186:15,142:25,152:40,214:65,216:35,245:75,258:80,236:45,240:40,282:85,279:60,295:100,294:100,315:100"},{"s":"leeuwin-estate-art-series-chardonnay","n":"Art Series Chardonnay","p":"Leeuwin Estate","t":"white","c":"Australia","r":"Western Australia","a":"Margaret River","g":["Chardonnay"],"pr":110,"abv":13.5,"e":"Barrel-fermented and aged about 11 months in French oak, largely new","sv":"10–12°C","d":"30 minutes when young","w":"5–20 years from vintage","ds":"One of the New World''s great Chardonnays: grapefruit, white nectarine and a hint of Gingin-clone fig, wrapped in toasted hazelnut and a flinty, struck-match edge. It is dense and powerful, yet the acidity runs straight down the middle, and it needs years to show its full complexity.","x":"284:3,285:72,286:3,287:60,288:72,289:82,290:88,291:60,292:0,293:20,36:65,54:55,53:40,56:40,43:40,35:30,58:30,22:25,203:45,157:50,156:30,147:35,137:30,177:30,176:15,221:45,230:55,224:30,237:60,255:70,249:60,238:45,248:75,259:60,266:40,282:90,279:60,305:100,298:100,303:100,312:100"},{"s":"grosset-polish-hill-riesling","n":"Polish Hill Riesling","p":"Grosset","t":"white","c":"Australia","r":"South Australia","a":"Clare Valley","g":["Riesling"],"pr":55,"abv":12.5,"e":"Cool-fermented and aged briefly in stainless steel; bottled under screwcap","sv":"7–10°C","d":"Not needed","w":"Now–20 years","ds":"Bone-dry Australian Riesling at its most chiselled: lime juice and zest, linden blossom and a stony, slate-like line from the hard ground of Polish Hill. Austere in youth, it slowly picks up toast and a little kerosene in bottle without losing its drive.","x":"284:2,285:92,286:0,287:42,288:32,289:72,290:80,291:0,292:0,293:15,35:95,40:60,34:45,36:35,46:40,86:35,85:35,75:15,110:15,136:75,139:60,138:20,140:30,191:15,192:10,225:60,230:75,228:70,239:55,249:90,243:85,240:85,258:75,261:80,279:80,282:90,305:100,306:100,308:100,303:100"},{"s":"tyrrells-vat-1-hunter-semillon","n":"Vat 1 Hunter Semillon","p":"Tyrrell''s","t":"white","c":"Australia","r":"New South Wales","a":"Hunter Valley","g":["Semillon"],"pr":50,"abv":10.5,"e":"Picked early, cold-fermented in stainless steel with no oak, then bottle-aged at the winery for several years before release","sv":"8–11°C","d":"Not needed","w":"On release–25 years","ds":"A wine that is unique to Australia: picked at around 10.5% alcohol, it is lean, grassy lemon when young, and with age turns to toast, honey and beeswax without any oak at all. Released with several years of bottle age, it is already showing that transformation while staying taut and mouth-watering.","x":"284:2,285:85,286:0,287:15,288:30,289:68,290:80,291:0,292:0,293:55,34:60,35:55,40:40,43:40,45:30,46:25,89:25,116:25,79:20,184:60,192:45,193:40,194:30,136:45,225:60,222:35,230:55,249:75,243:60,258:90,248:65,261:85,280:80,281:35,282:95,306:100,303:100,305:100,307:100"},{"s":"campbells-rutherglen-muscat","n":"Rutherglen Muscat","p":"Campbells","t":"fortified","c":"Australia","r":"Victoria","a":"Rutherglen","g":["Muscat à Petits Grains Rouge"],"pr":22,"abv":17.5,"e":"Fortified with neutral grape spirit; blended from a solera-style system of old oak casks, averaging several years of age","sv":"14–16°C","d":"Not needed","w":"Ready on release; keeps for weeks once opened","ds":"Liquid raisin and toffee: sun-dried Muscat, fig and date folded into caramel, brown sugar and roasted nut, with a whisper of rose from the grape itself. Long oak ageing in Rutherglen''s hot sheds makes it syrupy and luscious, and a little rancio keeps it from being only sweet.","x":"284:95,285:45,286:5,287:85,288:95,289:92,290:90,291:40,292:0,293:75,24:95,22:60,25:55,23:35,32:20,39:30,72:30,206:75,171:60,172:40,173:35,174:40,166:25,203:35,204:25,208:25,192:40,135:35,223:85,226:60,257:90,238:85,255:80,275:95,276:50,267:40,281:65,283:80,321:100,317:100,320:100"},{"s":"rockford-black-shiraz","n":"Black Shiraz","p":"Rockford","t":"sparkling","c":"Australia","r":"South Australia","a":"Barossa Valley","g":["Shiraz"],"pr":80,"abv":13.5,"e":"Base wine aged around three years in old oak, then traditional-method second fermentation and extended time on lees before disgorgement","sv":"12–14°C","d":"Not needed","w":"Now–15 years; improves with time after disgorgement","ds":"Australia''s cult sparkling red: blackberry, mulberry and plum foam with dark chocolate, licorice and Christmas-cake spice. A gentle sweetness and soft, velvety tannins carry the fruit, so it suits the roast turkey table as well as anything off the grill.","x":"284:20,285:55,286:40,287:55,288:65,289:80,290:72,291:30,292:90,293:35,12:80,14:60,15:50,17:45,27:30,30:30,168:45,126:50,135:35,123:20,185:25,148:15,234:55,233:30,213:45,226:50,257:75,250:60,238:55,272:85,260:50,280:55,282:55,300:100,299:100,298:100,301:100"},{"s":"penfolds-grange","n":"Grange","p":"Penfolds","t":"red","c":"Australia","r":"South Australia","a":"South Australia","g":["Shiraz","Cabernet Sauvignon"],"pr":900,"abv":14.5,"e":"Finishes fermentation in barrel; around 18 months in new American oak hogsheads","sv":"17–18°C","d":"2–3 hours when young","w":"15–50 years from vintage","ds":"Australia''s first-growth: a multi-regional Shiraz of enormous density, with blackberry, plum and mulberry wrapped in mocha, coconut and licorice from its new American oak. Built for half a century, it shuts down in youth and emerges decades later full of soy, leather and spice, with its plush power intact.","x":"284:3,285:62,286:88,287:75,288:95,289:95,290:95,291:82,292:0,293:20,12:90,15:75,17:45,13:40,14:40,168:70,167:60,166:40,156:55,160:45,157:50,126:65,127:25,135:40,120:25,98:15,195:20,185:20,198:20,213:60,216:50,227:45,237:95,238:85,255:95,245:90,251:60,248:85,259:85,282:100,279:60,294:100,295:100,297:100,315:100"},{"s":"cloudy-bay-sauvignon-blanc","n":"Sauvignon Blanc","p":"Cloudy Bay","t":"white","c":"New Zealand","r":"Marlborough","a":"Marlborough","g":["Sauvignon Blanc"],"pr":30,"abv":13,"e":"Cool-fermented in stainless steel; a small portion fermented in older French oak","sv":"7–9°C","d":"Not needed","w":"Now–3 years","ds":"The wine that put Marlborough on the map: passion fruit, gooseberry and pink grapefruit cut with freshly mown grass, green pepper and tomato leaf. It is vivid, crisp and very aromatic, and should be drunk in the first flush of youth.","x":"284:4,285:82,286:0,287:50,288:40,289:85,290:62,291:3,292:0,293:10,60:85,66:80,36:65,35:55,62:30,67:25,46:25,89:70,88:45,90:30,96:25,93:20,94:20,110:30,76:25,136:25,141:15,228:85,229:65,240:95,252:70,244:60,258:85,256:60,261:80,279:90,283:80,318:100,305:100,313:100,303:100,306:100"},{"s":"greywacke-wild-sauvignon","n":"Wild Sauvignon","p":"Greywacke","t":"white","c":"New Zealand","r":"Marlborough","a":"Marlborough","g":["Sauvignon Blanc"],"pr":35,"abv":13.5,"e":"Fermented with indigenous yeasts in old French barriques; around 10 months on lees with stirring","sv":"9–11°C","d":"15–30 minutes","w":"Now–8 years","ds":"Marlborough Sauvignon in a quieter key: the passion fruit and gooseberry are still there, but wild yeast and old barrels add flint, smoke and a creamy, savoury lees texture. It drinks more like a white Bordeaux or a Loire Sauvignon from a great site than like a classic Kiwi aromatic.","x":"284:4,285:75,286:3,287:55,288:60,289:82,290:78,291:30,292:0,293:20,60:55,66:50,36:55,43:35,53:35,56:30,45:30,89:35,88:20,96:15,102:25,147:45,137:40,158:25,178:25,177:30,203:20,136:35,221:50,232:30,224:40,248:75,242:50,253:25,249:50,260:70,266:70,265:35,279:55,282:45,305:100,298:100,318:100,303:100"},{"s":"felton-road-bannockburn-pinot-noir","n":"Bannockburn Pinot Noir","p":"Felton Road","t":"red","c":"New Zealand","r":"Central Otago","a":"Bannockburn","g":["Pinot Noir"],"pr":75,"abv":13.5,"e":"Biodynamic fruit, wild-fermented with some whole clusters; 11–13 months in French oak, about a quarter new; unfined and unfiltered","sv":"14–16°C","d":"30 minutes","w":"3–15 years from vintage","ds":"Central Otago''s reference point: dark cherry and raspberry lifted by violet, wild thyme and five-spice, over a stony schist base. The fruit is ripe and concentrated, but silky tannins and bright acidity keep it graceful.","x":"284:2,285:68,286:50,287:60,288:55,289:78,290:78,291:35,292:0,293:18,14:75,1:60,3:45,9:40,71:40,72:25,102:45,111:20,134:35,123:20,148:25,149:12,140:30,139:25,157:15,156:12,212:60,214:50,229:50,231:45,236:75,252:65,240:60,255:55,249:60,262:30,265:40,279:60,282:70,299:100,304:100,310:100,295:100"},{"s":"craggy-range-gimblett-gravels-syrah","n":"Gimblett Gravels Syrah","p":"Craggy Range","t":"red","c":"New Zealand","r":"Hawke''s Bay","a":"Gimblett Gravels","g":["Syrah"],"pr":40,"abv":13.5,"e":"About 15 months in French oak, roughly 20% new","sv":"15–17°C","d":"30–60 minutes","w":"Now–12 years","ds":"Cool-climate Syrah closer to Crozes or Saint-Joseph than to the Barossa: cracked black pepper and violet over blackberry and boysenberry, with smoked meat and olive on the edges. The free-draining gravels give it a fine-grained, savoury frame and a fresh, peppery finish.","x":"284:2,285:65,286:60,287:55,288:60,289:75,290:72,291:35,292:0,293:18,120:85,121:35,12:60,16:45,15:40,18:35,71:70,190:35,112:35,126:25,143:25,140:40,142:20,159:15,156:12,214:65,229:45,230:40,242:60,252:65,236:60,240:55,245:50,279:65,282:60,295:100,297:100,299:100,301:100"},{"s":"kanonkop-kadette-pinotage","n":"Kadette Pinotage","p":"Kanonkop","t":"red","c":"South Africa","r":"Stellenbosch","a":"Stellenbosch","g":["Pinotage"],"pr":18,"abv":14,"e":"Fermented in traditional open concrete kuipe with manual punch-downs; about 12 months in second- and third-fill French oak","sv":"15–17°C","d":"30 minutes","w":"Now–6 years","ds":"Pinotage made by the house that champions it: mulberry, black plum and dark cherry with the grape''s typical smoky, roasted-coffee tone and a hint of tar. Tannins are firm but ripe, so it works best with a braai, or with anything else that has been charred.","x":"284:3,285:55,286:60,287:68,288:68,289:75,290:60,291:30,292:0,293:15,17:60,15:60,14:60,12:40,9:35,63:15,158:50,166:35,167:25,168:20,198:25,151:30,153:25,114:15,135:20,126:20,216:50,218:30,229:45,227:35,241:55,244:50,246:40,242:40,256:55,260:50,279:70,283:60,300:100,302:100,294:100,297:100"},{"s":"badenhorst-secateurs-chenin-blanc","n":"Secateurs Chenin Blanc","p":"A.A. Badenhorst Family Wines","t":"white","c":"South Africa","r":"Coastal Region","a":"Swartland","g":["Chenin Blanc"],"pr":18,"abv":13,"e":"Wild-fermented; aged on lees in concrete tanks and old foudres","sv":"9–11°C","d":"Not needed","w":"Now–5 years","ds":"Dry-farmed old bush-vine Chenin from the granite and shale of the Paardeberg: yellow apple, quince and pear with chamomile, hay and a salty, stony finish. Lees ageing gives it a waxy texture, and it delivers far more character than its price suggests.","x":"284:4,285:75,286:3,287:50,288:55,289:68,290:65,291:8,292:0,293:15,47:65,51:55,49:50,34:45,53:35,58:20,45:30,79:30,116:35,85:25,192:15,194:20,136:45,141:30,140:25,222:50,232:30,229:50,228:40,240:70,242:40,243:45,256:65,278:55,260:45,266:50,265:35,279:75,283:65,298:100,296:100,308:100,318:100,319:100"},{"s":"hamilton-russell-vineyards-chardonnay","n":"Chardonnay","p":"Hamilton Russell Vineyards","t":"white","c":"South Africa","r":"Cape South Coast","a":"Hemel-en-Aarde Valley","g":["Chardonnay"],"pr":45,"abv":13,"e":"Barrel-fermented; about 9 months in French oak, roughly a third new, with lees contact","sv":"10–12°C","d":"20 minutes","w":"Now–10 years","ds":"A Burgundian-minded Chardonnay from stony, clay-rich shale near the cold Atlantic: lemon, green apple and white peach with hazelnut, a flinty edge and an oyster-shell salinity. It is taut and precise, with oak that adds texture rather than flavour.","x":"284:2,285:75,286:2,287:50,288:58,289:72,290:78,291:40,292:0,293:20,34:55,35:35,36:30,45:30,46:35,49:40,53:35,203:40,202:20,157:30,147:30,137:35,177:20,178:20,136:55,141:30,144:25,221:35,230:55,225:30,249:75,236:75,243:70,258:60,260:30,259:30,266:40,279:60,282:70,303:100,305:100,298:100,312:100"},{"s":"graham-beck-brut-nv","n":"Brut NV","p":"Graham Beck","t":"sparkling","c":"South Africa","r":"Western Cape","a":"Western Cape","g":["Chardonnay","Pinot Noir"],"pr":20,"abv":12,"e":"Méthode Cap Classique (traditional method); about 15 months on lees before disgorgement","sv":"6–8°C","d":"Not needed","w":"Now–3 years","ds":"South Africa''s benchmark Cap Classique: green apple, lemon and pear with a gentle brioche and biscuit note from time on the lees. Crisp, fine-beaded and well balanced, it is one of the best-value traditional-method sparklers made anywhere.","x":"284:10,285:82,286:0,287:35,288:40,289:60,290:62,291:0,292:95,293:20,46:65,34:60,47:35,49:35,53:25,40:30,178:45,179:35,181:35,180:30,202:20,85:20,138:25,233:75,228:80,240:85,236:55,256:75,258:55,272:95,261:55,279:70,283:80,323:100,319:100,306:100,307:100,305:100"},{"s":"alamos-malbec","n":"Malbec","p":"Alamos","t":"red","c":"Argentina","r":"Mendoza","a":"Mendoza","g":["Malbec"],"pr":12,"abv":13.5,"e":"A portion aged about 8 months in French and American oak; the rest in tank","sv":"15–17°C","d":"Not needed","w":"Now–4 years","ds":"Everyday Mendoza Malbec done right: dark plum, blackberry and black cherry with a violet lift and a dusting of mocha and vanilla. Soft, ripe tannins make it easy to drink, whether with a weeknight steak or with tacos.","x":"284:6,285:50,286:50,287:62,288:65,289:68,290:52,291:30,292:0,293:12,15:85,12:60,14:55,16:35,28:25,71:45,167:35,156:35,170:25,160:12,135:25,126:15,153:15,213:50,226:50,231:55,229:45,244:85,241:60,256:90,250:50,279:85,283:90,302:100,294:100,300:100,311:100,309:100"},{"s":"zuccardi-concreto-malbec","n":"Concreto Malbec","p":"Zuccardi Valle de Uco","t":"red","c":"Argentina","r":"Mendoza","a":"Paraje Altamira","g":["Malbec"],"pr":50,"abv":13.5,"e":"Whole-berry wild fermentation and ageing in uncoated concrete vessels; no oak","sv":"15–17°C","d":"45 minutes","w":"Now–12 years","ds":"High-altitude Malbec stripped of oak to show its site: violet, lavender and crunchy red and black cherry over the chalky, calcareous stones of Paraje Altamira. The tannins feel like chalk dust, the acidity is high, and it tastes more of rock than of ripeness.","x":"284:2,285:70,286:62,287:55,288:58,289:78,290:78,291:0,292:0,293:15,14:60,9:50,3:45,1:45,16:30,71:80,78:30,111:30,102:20,122:20,138:65,140:55,136:35,142:20,215:70,214:45,229:55,230:55,243:85,240:80,249:75,236:65,252:60,261:85,265:40,279:70,282:65,295:100,294:100,310:100,315:100"},{"s":"colome-torrontes","n":"Torrontés","p":"Bodega Colomé","t":"white","c":"Argentina","r":"Salta","a":"Calchaquí Valley","g":["Torrontés"],"pr":15,"abv":13.5,"e":"Cool-fermented and aged in stainless steel","sv":"7–9°C","d":"Not needed","w":"Now–2 years","ds":"Torrontés from some of the world''s highest vineyards: orange blossom, jasmine and rose leap from the glass, followed by lychee, white peach and grapey Muscat fruit. The palate is drier and sleeker than the nose suggests, finishing with a pithy citrus snap.","x":"284:5,285:60,286:0,287:60,288:48,289:85,290:55,291:0,292:0,293:10,61:60,53:55,55:30,70:55,36:35,40:30,45:35,41:25,75:75,77:70,72:55,85:40,74:35,80:12,110:20,232:30,228:40,229:45,252:95,240:65,244:70,256:75,261:85,279:90,283:90,308:100,307:100,323:100,313:100,305:100"},{"s":"el-enemigo-cabernet-franc","n":"Cabernet Franc","p":"El Enemigo","t":"red","c":"Argentina","r":"Mendoza","a":"Mendoza","g":["Cabernet Franc","Malbec"],"pr":28,"abv":14,"e":"About 15 months in French oak, mostly large foudres and used barrels","sv":"15–17°C","d":"30–60 minutes","w":"Now–10 years","ds":"Alejandro Vigil''s take on Argentina''s rising star grape: red plum, black cherry and cassis cut with tobacco leaf, dried herbs and a gentle green-pepper bite. Fruit from high-altitude Gualtallary gives it graphite-like minerality, a fine, dusty tannin and plenty of freshness.","x":"284:2,285:62,286:62,287:65,288:65,289:78,290:72,291:35,292:0,293:18,14:55,3:50,9:45,13:45,12:30,88:35,92:15,119:45,111:40,102:25,71:35,142:40,140:35,138:25,120:30,170:20,159:25,214:55,217:30,229:45,242:55,240:55,245:55,252:50,248:55,260:55,279:60,282:55,295:100,294:100,314:100,301:100"},{"s":"don-melchor-cabernet-sauvignon","n":"Don Melchor Cabernet Sauvignon","p":"Viña Don Melchor","t":"red","c":"Chile","r":"Maipo Valley","a":"Puente Alto","g":["Cabernet Sauvignon","Cabernet Franc","Merlot","Petit Verdot"],"pr":135,"abv":14.5,"e":"About 15 months in French oak barriques, the majority new","sv":"16–18°C","d":"1–2 hours when young","w":"5–25 years from vintage","ds":"Chile''s grand-cru Cabernet, from alluvial terraces at the foot of the Andes: pure cassis and black cherry with Puente Alto''s signature mint and dried herbs, set in cedar and graphite. Polished and long, it pairs Bordeaux structure with the clear, sunny fruit of the Maipo.","x":"284:2,285:62,286:78,287:65,288:80,289:82,290:85,291:60,292:0,293:20,13:90,14:55,12:50,15:30,97:45,98:20,105:15,111:25,159:55,142:50,163:30,156:30,157:35,167:25,186:25,140:35,153:25,214:70,219:55,245:85,236:65,247:70,255:70,258:60,259:60,282:90,279:60,294:100,295:100,315:100,297:100"},{"s":"lapostolle-cuvee-alexandre-carmenere","n":"Cuvée Alexandre Carmenère","p":"Lapostolle","t":"red","c":"Chile","r":"Colchagua Valley","a":"Apalta","g":["Carmenère"],"pr":25,"abv":14.5,"e":"About 10 months in French oak barrels","sv":"16–18°C","d":"30 minutes","w":"Now–8 years","ds":"Carmenère grown in the warm Apalta amphitheatre: blackberry and plum with the grape''s green-pepper streak and a dusting of black pepper, oregano and tobacco. French oak adds mocha and smoke, and the tannins are round, velvety and easy.","x":"284:3,285:52,286:58,287:72,288:72,289:78,290:68,291:45,292:0,293:15,12:60,15:60,14:40,16:25,88:70,92:25,90:15,111:35,107:30,119:35,120:70,135:25,123:20,168:35,167:35,166:25,156:25,158:30,213:60,226:50,231:45,241:55,242:45,250:55,244:50,259:40,279:70,283:55,300:100,309:100,294:100,295:100,314:100"},{"s":"de-martino-viejas-tinajas-cinsault","n":"Viejas Tinajas Cinsault","p":"De Martino","t":"red","c":"Chile","r":"Itata Valley","a":"Itata","g":["Cinsault"],"pr":25,"abv":13,"e":"Dry-farmed old vines; wild-fermented and aged about a year in old clay tinajas, no oak","sv":"13–15°C","d":"Not needed","w":"Now–6 years","ds":"Old, dry-farmed Cinsault from Itata''s granite hills, fermented and aged in antique clay tinajas: red cherry, raspberry and pomegranate with a dusty, earthy edge and a hint of white pepper. Light, juicy and a little rustic, this is old-vine Chile with its makeup off, and it takes a chill well.","x":"284:2,285:68,286:35,287:45,288:40,289:62,290:60,291:0,292:0,293:20,1:75,3:60,4:45,8:35,7:30,9:30,72:30,83:25,121:30,111:25,114:20,151:40,152:45,153:30,140:25,215:45,212:30,229:70,231:45,240:75,246:45,242:45,253:20,256:60,277:90,278:85,265:70,261:60,279:60,283:70,301:100,311:100,304:100,298:100,314:100"},{"s":"bodega-garzon-tannat-reserva","n":"Tannat Reserva","p":"Bodega Garzón","t":"red","c":"Uruguay","r":"Maldonado","a":"Garzón","g":["Tannat"],"pr":20,"abv":14,"e":"Fermented in concrete; a portion aged in large French oak casks","sv":"16–18°C","d":"45 minutes","w":"Now–10 years","ds":"Uruguay''s national grape grown on granite hills near the Atlantic: blackberry, damson and dark plum with cocoa, licorice and a faint sea-breeze salinity. The tannins are serious and chewy, but sea-cooled acidity keeps the whole thing lively, and it is built for grilled meat.","x":"284:3,285:68,286:85,287:65,288:75,289:75,290:70,291:25,292:0,293:15,12:75,15:60,14:45,16:35,20:35,71:35,168:40,170:35,166:20,126:35,120:25,135:20,142:25,141:15,140:30,216:75,227:55,220:30,255:60,237:60,245:75,240:40,251:40,260:45,279:75,282:55,294:100,300:100,297:100,315:100"},{"s":"domaine-tempier-bandol-rose","n":"Bandol Rosé","p":"Domaine Tempier","t":"rose","c":"France","r":"Provence","a":"Bandol","g":["Mourvèdre","Grenache","Cinsault","Carignan"],"pr":48,"abv":13.5,"e":"Direct press and short maceration; fermented and aged in stainless steel and old foudres for several months","sv":"9–11°C","d":"Not needed","w":"Now–6 years","ds":"The benchmark for serious Provençal pink: Mourvèdre brings a savory, almost meaty backbone beneath wild strawberry, blood orange and crushed garrigue. Salmon-copper in colour, it has the grip and saline length to stand beside bouillabaisse and grilled lamb.","x":"284:3,285:62,286:12,287:52,288:55,289:72,290:80,291:5,292:0,293:20,5:70,38:65,6:50,11:35,39:40,106:75,102:40,100:30,121:35,143:20,141:60,138:30,136:30,189:15,72:20,228:55,232:45,229:40,230:40,242:80,248:65,258:80,245:50,236:60,260:40,282:60,279:60,295:100,305:100,303:100,311:100,300:100"},{"s":"muga-rosado-rioja","n":"Rosado","p":"Bodegas Muga","t":"rose","c":"Spain","r":"Rioja","a":"Rioja DOCa","g":["Garnacha","Viura","Tempranillo"],"pr":15,"abv":13.5,"e":"Free-run juice fermented cool in stainless steel, then rested on fine lees for a few months","sv":"7–10°C","d":"Not needed","w":"Now–2 years","ds":"A pale raspberry-pink Rioja that favours juicy Garnacha fruit over restraint: strawberry, cherry and a lick of white peach, tied together with a mouth-watering saline edge. Plush and friendly, but with enough acidity to keep tapas of every sort in play.","x":"284:4,285:58,286:6,287:55,288:45,289:60,290:55,291:0,292:0,293:10,4:80,1:65,3:50,11:40,53:30,48:20,85:30,72:25,136:15,141:25,121:20,179:12,221:15,229:75,224:45,228:50,231:35,240:85,244:80,256:85,250:40,261:70,266:30,283:85,279:85,301:100,305:100,319:100,323:100,298:100"},{"s":"vacheron-sancerre-rose","n":"Sancerre Rosé","p":"Domaine Vacheron","t":"rose","c":"France","r":"Loire","a":"Sancerre","g":["Pinot Noir"],"pr":38,"abv":13,"e":"Biodynamically farmed; gentle press, fermented and aged in stainless steel and neutral barrels on fine lees","sv":"9–11°C","d":"Not needed","w":"Now–4 years","ds":"Sancerre''s quiet red side, in the palest salmon: tart cherry, cranberry and wild strawberry laced with a flinty, kimmeridgian chalkiness. Taut, slender and quietly intense, it drinks more like a light Pinot Noir in a white wine''s clothing.","x":"284:3,285:78,286:8,287:40,288:35,289:60,290:68,291:3,292:0,293:12,2:65,5:70,7:50,6:50,36:35,40:25,10:20,85:30,72:20,137:60,138:60,136:50,141:30,95:12,121:15,228:75,230:70,225:50,249:80,236:75,240:85,243:80,254:45,261:50,266:30,279:80,318:100,304:100,313:100,306:100,323:100"},{"s":"bedrock-ode-to-lulu-rose","n":"Ode to Lulu Rosé","p":"Bedrock Wine Co.","t":"rose","c":"USA","r":"California","a":"Sonoma Valley","g":["Mourvèdre","Grenache","Carignan"],"pr":30,"abv":12.5,"e":"Old-vine Mourvèdre direct-pressed and fermented with native yeasts in neutral barrels and stainless steel; aged on lees for six months","sv":"9–11°C","d":"Not needed","w":"Now–4 years","ds":"Morgan Peter Twain-Peterson''s tribute to Bandol, built from century-old Mourvèdre vines: ripe strawberry and blood orange, fennel-edged herbs and a savory, almost bloody core. It carries real mid-palate weight, yet a razor of acidity keeps it from ever tasting heavy.","x":"284:3,285:68,286:10,287:38,288:50,289:70,290:72,291:5,292:0,293:12,4:75,38:60,3:45,1:40,8:35,11:30,39:30,100:40,106:45,102:25,72:20,121:30,143:25,138:20,136:25,141:20,229:70,228:55,232:40,224:35,242:65,240:75,248:55,236:50,255:45,278:80,265:55,260:45,266:35,279:75,300:100,298:100,296:100,313:100,304:100"},{"s":"clos-cibonne-cuvee-speciale-tibouren-rose","n":"Cuvée Spéciale des Vignettes Rosé","p":"Clos Cibonne","t":"rose","c":"France","r":"Provence","a":"Côtes de Provence Cru Classé","g":["Tibouren","Grenache"],"pr":36,"abv":13,"e":"Tibouren fermented in stainless steel, then aged under a light flor-like veil in century-old Slavonian oak foudres for 8 months","sv":"10–12°C","d":"Not needed","w":"Now–8 years","ds":"Tibouren, Provence''s rare and singular coastal grape, gives a rosé that is amber-tinged and quietly eccentric: dried orange, wild herbs, a nutty whisper of flor and a briny sea-air finish. A thinking person''s pink that gains complexity with a few years in bottle.","x":"284:3,285:60,286:10,287:50,288:55,289:75,290:82,291:12,292:0,293:30,39:60,5:50,32:35,41:40,6:35,8:25,106:70,102:35,104:20,121:35,123:15,141:70,144:30,138:25,202:40,207:30,203:15,193:15,222:30,232:45,224:40,228:40,242:75,248:80,258:60,236:55,253:20,260:75,267:20,282:65,280:40,303:100,305:100,298:100,310:100,315:100"},{"s":"valentini-cerasuolo-d-abruzzo","n":"Cerasuolo d''Abruzzo","p":"Valentini","t":"rose","c":"Italy","r":"Abruzzo","a":"Cerasuolo d''Abruzzo DOC","g":["Montepulciano"],"pr":85,"abv":13.5,"e":"Native-yeast fermentation after brief skin contact; aged in large old Slavonian botti for around 12 months with no fining or filtration","sv":"10–12°C","d":"30 minutes in a carafe to open up","w":"Now–12 years","ds":"Edoardo Valentini''s cult cherry-red rosato is a pink only in name: wild cherry, blood orange and dried herbs, with a gentle tannic backbone and a long, savory finish. It has the structure to age like a light red and the vivid freshness to drink as a rosé.","x":"284:3,285:65,286:15,287:55,288:62,289:78,290:88,291:10,292:0,293:30,2:80,1:65,9:40,8:40,38:45,26:30,3:30,111:50,107:25,126:20,120:30,72:20,143:35,152:30,153:25,136:20,116:15,189:10,214:45,229:55,232:55,231:35,242:80,248:80,245:60,255:55,246:35,258:70,260:85,265:60,282:80,280:35,296:100,301:100,311:100,295:100,315:100"}]'::jsonb);
